import 'package:mad_flutter_practicum/domain/domain.dart';
import 'package:provider/provider.dart';

class DashboardPage extends StatefulWidget {
  const DashboardPage({super.key});

  @override
  State<DashboardPage> createState() => _DashboardPageState();
}

class _DashboardPageState extends State<DashboardPage> {
  late Future<Map<String, dynamic>> _dashboardFuture;

  @override
  void initState() {
    super.initState();
    _initData();
  }

  void _initData() {
    final currencyRepository = context.read<CurrencyRepository>();
    final newsRepository = context.read<NewsRepository>();

    _dashboardFuture = Future.wait([
      currencyRepository.fetchRates(const CurrencyPageRequest(base: 'USD')),
      newsRepository.loadNewsFeed(const NewsFeedFilter(forceRefresh: true)),
    ]).then((List<dynamic> results) {
      final CurrencyPage page = results[0] as CurrencyPage;
      final List<NewsModel> news = results[1] as List<NewsModel>;

      currencyRepository.saveCurrencyList(page.items);

      return <String, dynamic>{'currencies': page.items, 'news': news};
    });
  }

  @override
  Widget build(BuildContext context) {
    final AppLocalizations loc = context.loc;

    return Scaffold(
      appBar: AppBar(title: Text(loc.dashboard)),
      body: FutureBuilder<Map<String, dynamic>>(
        future: _dashboardFuture,
        builder: (BuildContext context, AsyncSnapshot<Map<String, dynamic>> snapshot) {
          if (!snapshot.hasData) {
            return const Center(child: CircularProgressIndicator());
          }

          final Map<String, dynamic> data = snapshot.data!;
          final List<CurrencyModel> currencies = data['currencies'] as List<CurrencyModel>;
          final List<NewsModel> news = data['news'] as List<NewsModel>;

          return ListView(
            padding: const EdgeInsets.all(16),
            children: [
              Text(loc.dashboardExchangeRates, style: Theme.of(context).textTheme.titleMedium),
              ...currencies.map((CurrencyModel currency) => Padding(
                padding: const EdgeInsets.only(top: 8),
                child: Text('${currency.name}: ${currency.value}'),
              )),
              const SizedBox(height: 16),
              Text(loc.dashboardNews, style: Theme.of(context).textTheme.titleMedium),
              ...news.map((NewsModel newsItem) => Padding(
                padding: const EdgeInsets.only(top: 8),
                child: Text(newsItem.title),
              )),
            ],
          );
        },
      ),
    );
  }
}
